// Build messages array with chat history
const chatHistory = $json.body?.chat_history || [];
const currentMessage = $json.body?.message || '';
const tenantId = $json.body?.tenant_id || 'unknown';
const businessName = $json.body?.business_name || 'Our Business';
const sessionId = $json.body?.session_id || 'default';

// System prompt
const systemPrompt = `You are Parker, a friendly and professional AI receptionist for ${businessName}.

Your capabilities:
- Help customers book appointments
- Check availability for specific dates/times
- Answer questions about services
- Provide business information

Rules:
- Be concise and conversational (2-3 sentences max)
- Ask for missing info one thing at a time
- Use natural language for dates/times
- Always confirm details before booking
- Today's date is ${new Date().toISOString().split('T')[0]}

Tenant ID: ${tenantId}`;

// Build messages array
const messages = [
  { role: 'system', content: systemPrompt }
];

// Add chat history
for (const msg of chatHistory) {
  messages.push({
    role: msg.role || 'user',
    content: msg.content || msg.text || ''
  });
}

// Add current message
messages.push({ role: 'user', content: currentMessage });

return {
  messages,
  sessionId,
  tenantId,
  businessName
};

